UPDATE loan_account
SET loan_type = #{loanType}, principal_amount = #{principalAmount}, current_balance = #{currentBalance}, interest_rate = #{interestRate}, rate_type = #{rateType}, repayment_type = #{repaymentType}, disbursed_at = #{disbursedAt}, maturity_at = #{maturityAt}, loan_status = #{loanStatus}, data_as_of_at = #{dataAsOfAt}, updated_at = #{updatedAt}, prepayment_fee_rate = #{prepaymentFeeRate}, prepayment_fee_end_date = #{prepaymentFeeEndDate}
WHERE loan_account_id = #{loanAccountId}
